#!/usr/bin/env node
/**
 * One-time script to backfill CHANGELOG.md from all existing GitHub releases.
 *
 * The release bodies were generated by semantic-release and already contain
 * formatted markdown. This script normalizes the heading levels to match what
 * @semantic-release/changelog produces (## for version, ### for sections) and
 * writes them all out newest-first.
 *
 * Usage: node scripts/backfill-changelog.mjs
 */

import { execSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const REPO = 'arsdehnel/rwsdk-jeopardy';

console.log('Fetching releases from GitHub...');

const releases = JSON.parse(
	execSync(`gh api --paginate repos/${REPO}/releases?per_page=100`, {
		encoding: 'utf8',
	}),
);

// gh api --paginate concatenates pages as JSON arrays; flatten in case of multiple pages
const allReleases = [].concat(...(Array.isArray(releases[0]) ? releases : [releases]));

console.log(`Found ${allReleases.length} releases.`);

// GitHub API returns newest-first, which is the correct changelog order
const entries = allReleases
	.filter(r => !r.draft && r.body?.trim())
	.map(r => {
		// Older releases used # for the version heading; normalize to ## to match
		// what @semantic-release/changelog produces.
		const body = r.body
			.trim()
			.replace(/^# \[/m, '## [') // version heading
			.replace(/^## ##/m, '##'); // guard against double-replace if already ##
		return body;
	});

const changelog = `# Changelog\n\n${entries.join('\n\n')}\n`;

writeFileSync('CHANGELOG.md', changelog);
console.log(`Wrote ${entries.length} entries to CHANGELOG.md.`);
